def _scan_shell_quoted_literal(rest: str) -> tuple[str | None, bool]:
    if not rest:
        return None, False
    quote = rest[0]
    if quote == "'":
        end = rest.find("'", 1)
        if end < 0:
            return None, False
        literal = rest[1:end]
        suffix = rest[end + 1:]
        return (literal, True) if suffix[:1].isspace() else (None, False)
    if quote != '"':
        return None, False
    body: list[str] = []
    escaped = False
    bare_dollar = False
    for index, char in enumerate(rest[1:], start=1):
        if escaped:
            if char in _DOUBLE_QUOTED_LITERAL_ESCAPES:
                body.append(char)
            else:
                body.append("\\")
                body.append(char)
            escaped = False
            continue
        if char == "\\":
            escaped = True
            continue
        if char == "$":
            bare_dollar = True
            body.append(char)
            continue
        if char == '"':
            suffix = rest[index + 1:]
            if bare_dollar or not suffix[:1].isspace():
                return None, False
            return "".join(body), True
        body.append(char)
    return None, False


