    return out


def _is_security_block(block: str) -> bool:
    normalized = file_oos._strip_md_emphasis(block)  # pyright: ignore[reportPrivateUsage]
    return bool(file_oos._SECURITY_HEADER_RE.search(block) or file_oos._SECURITY_FOCUS_RE.search(normalized))  # pyright: ignore[reportPrivateUsage]


def _accepted_input_paths(tmpdir: Path) -> tuple[Path, ...]:
    return (
        tmpdir / "oos-accepted-main-agent.md",
        file_oos.resolve_design_oos_path(tmpdir),
        tmpdir / "oos-accepted-review.md",
    )


def _working_batch(tmpdir: Path) -> tuple[list[AcceptedBlock], list[FiledIssue]]:
    seen: set[str] = set()
    blocks: list[AcceptedBlock] = []
    already: list[FiledIssue] = []
    for path in _accepted_input_paths(tmpdir):
        if not path.is_file():
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        for item in file_oos._parse_oos_blocks(text):  # pyright: ignore[reportPrivateUsage]
            if _is_security_block(item.body):
                continue
            filed_urls = _FILED_URL_LINE_RE.findall(item.body)
            if filed_urls:
                already.extend(FiledIssue(item.title, url, duplicate=True) for url in filed_urls)
                continue
            normalized = file_oos._normalize_title(item.title).lower()  # pyright: ignore[reportPrivateUsage]
            if normalized in seen:
                continue
            seen.add(normalized)
            blocks.append(AcceptedBlock(item.title, item.body))
    return blocks, already


def _render_blocks(blocks: list[AcceptedBlock]) -> str:
    rendered: list[str] = []
    for index, block in enumerate(blocks, start=1):
        rendered.append(re.sub(r"^### OOS_\d+:", f"### OOS_{index}:", block.body, count=1, flags=re.MULTILINE))
    return "\n\n".join(rendered).rstrip() + ("\n" if rendered else "")


def _append_tool_failure(tmpdir: Path, site: str, tool: str, rc: int, output: str) -> None:
    file_oos._append_failure_log(tmpdir / "execution-issues.md", site, tool, rc, output)  # pyright: ignore[reportPrivateUsage]


def _append_warning(tmpdir: Path, message: str) -> None:
    file_oos._append_run_log_warning(tmpdir, f"- **oos file**: {message}")  # pyright: ignore[reportPrivateUsage]


def _sentinel_urls(tmpdir: Path) -> list[FiledIssue]:
    sentinel = tmpdir / "oos-issues-created.md"
    if not sentinel.is_file():
        return []
    text = sentinel.read_text(encoding="utf-8", errors="replace")
    urls = _GITHUB_URL_RE.findall(text)
    return [FiledIssue("Recovered OOS disposition", url, duplicate=True) for url in urls]


def _codex_available() -> bool:
    raw = os.environ.get("LARCH_OOS_CODEX_AVAILABLE", "")
    if raw.lower() in {"true", "1", "yes"}:
        return True
    if raw.lower() in {"false", "0", "no"}:
        return False
    return shutil.which("codex") is not None


def _valid_combined_output(text: str, original_count: int) -> bool:
    if not text.strip():
        return False
    try:
        file_oos._validate_issue_cap_input(text)  # pyright: ignore[reportPrivateUsage]
    except ValueError:
        return False
    count = len(file_oos._parse_oos_blocks(text))  # pyright: ignore[reportPrivateUsage]
    return 0 < count <= original_count


def _maybe_combine_with_codex(tmpdir: Path, text: str, *, codex_timeout: int) -> str:
    original_count = len(file_oos._parse_oos_blocks(text))  # pyright: ignore[reportPrivateUsage]
    if original_count <= 1:
        return text
    input_path = tmpdir / "oos-combine-input.md"
    output_path = tmpdir / "oos-combine-codex-output.md"
    prompt_path = tmpdir / "oos-combine-prompt.md"
    input_path.write_text(text, encoding="utf-8")
    prompt_path.write_text(
        "Aggressively combine accepted out-of-scope observations unless they are clearly unrelated.\n"
        "Return only valid markdown blocks shaped as `### OOS_N:` items.\n"
        "Preserve actionable details and do not increase the item count.\n\n"
        f"Input file: {input_path}\n\n"
        "## Batch markdown\n\n"
        f"{text.rstrip()}\n",
        encoding="utf-8",
    )
    if not _codex_available():
        _append_warning(tmpdir, "Codex unavailable; filing the pre-combine OOS batch.")
        return text
    result = _run_cli(
        [
            "agent",
            "launch-codex-exec",
            "--output",
            str(output_path),
            "--timeout",
            str(codex_timeout),
            "--prompt-file",
            str(prompt_path),
            "--sandbox",
            "read-only",
            "--workdir",
            str(_repo_root()),
            "--add-dir",
            str(tmpdir),
        ],
    )
    if result.returncode != 0 or not output_path.is_file():
        _append_warning(tmpdir, "Codex combine failed; filing the pre-combine OOS batch.")
        return text
    combined = output_path.read_text(encoding="utf-8", errors="replace")
    if not _valid_combined_output(combined, original_count):
        _append_warning(tmpdir, "Codex combine output was invalid; filing the pre-combine OOS batch.")
        return text
    return combined


def _wrap_oos_body(body: str, *, reviewer: str, phase: str, vote: str) -> str:
    return (
        "## Out-of-Scope Observation\n\n"
        f"**Surfaced by**: {reviewer or 'N/A'}\n"
        f"**Phase**: {phase or 'implement'}\n"
        f"**Vote tally**: {vote or 'N/A'}\n\n"
        "## Description\n\n"
        f"{body.rstrip()}\n\n"
        "---\n"
        "*This issue was automatically created by the larch `/implement` workflow from an out-of-scope observation surfaced during the workflow.*\n"
    )


def _parse_intra_batch_deps(path: Path) -> list[tuple[int, int]]:
    if not path.is_file() or path.stat().st_size == 0:
        return []
    edges: list[tuple[int, int]] = []
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        if not line.strip():
            continue
        parts = line.split("\t")
        if len(parts) == _INTRA_BATCH_DEP_FIELD_COUNT and parts[0].isdigit() and parts[1].isdigit():
            edges.append((int(parts[0]), int(parts[1])))
    return edges


def _topological_create_order(total: int, edges: list[tuple[int, int]]) -> list[int]:
    if total <= 0:
        return []
    if not edges:
        return list(range(1, total + 1))
    blocked_by: dict[int, set[int]] = {index: set() for index in range(1, total + 1)}
    blocks: dict[int, set[int]] = {index: set() for index in range(1, total + 1)}
    for blocker, blocked in edges:
        if not (1 <= blocker <= total and 1 <= blocked <= total) or blocker == blocked:
            continue
        blocked_by[blocked].add(blocker)
        blocks[blocker].add(blocked)
    ready = sorted(index for index in range(1, total + 1) if not blocked_by[index])
    order: list[int] = []
    while ready:
        current = ready.pop(0)

--- more ---
        current = ready.pop(0)
        order.append(current)
        for dependent in sorted(blocks[current]):
            blocked_by[dependent].discard(current)
            if not blocked_by[dependent]:
                ready.append(dependent)
        ready.sort()
    if len(order) != total:
        return list(range(1, total + 1))
    return order


def _probe_tracking_blocker(tmpdir: Path, repo: str, issue_number: str) -> bool:
    if not issue_number or not issue_number.isdigit():
        return True
    if not repo:
        _append_tool_failure(tmpdir, "step-9a1-oos-file", "blocker probe", 1, "missing repo for --blocked-by-issue probe")
        return False
    gh_path = shutil.which("gh")
    if gh_path is None:
        _append_tool_failure(tmpdir, "step-9a1-oos-file", "blocker probe", 1, "missing gh for --blocked-by-issue probe")
        return False
    result = subprocess.run(
        [gh_path, "api", f"/repos/{repo}/issues/{issue_number}", "--jq", ".number"],
        text=True,
        capture_output=True,
        check=False,
    )
    if result.returncode != 0 or not result.stdout.strip().isdigit():
        detail = (result.stderr or result.stdout or "blocker issue probe failed").strip()
        _append_tool_failure(tmpdir, "step-9a1-oos-file", "gh api blocker probe", result.returncode, detail)
        return False
    return True


def _cleanup_created_issues(_tmpdir: Path, filed: list[FiledIssue], *, repo: str) -> None:
    for issue in filed:
        if issue.url.startswith("skipped://") or issue.duplicate:
            continue
        number = issue.url.rsplit("/", 1)[-1]
        if not number.isdigit():
            continue
        _ = _run_cli(["issue", "cleanup-failed", "--issue-number", number, *([] if not repo else ["--repo", repo])])


def _body_file_for_item(tmpdir: Path, item_index: int, fields: dict[str, str]) -> Path:
    raw_path = Path(fields.get(f"ITEM_{item_index}_BODY_FILE", ""))
    body = raw_path.read_text(encoding="utf-8", errors="replace") if raw_path.is_file() else ""
    body = file_oos._sanitize_public_text(body)  # pyright: ignore[reportPrivateUsage]
    reviewer = file_oos._sanitize_public_text(fields.get(f"ITEM_{item_index}_REVIEWER", ""))  # pyright: ignore[reportPrivateUsage]
    phase = file_oos._sanitize_public_text(fields.get(f"ITEM_{item_index}_PHASE", "implement"))  # pyright: ignore[reportPrivateUsage]
    vote = file_oos._sanitize_public_text(fields.get(f"ITEM_{item_index}_VOTE_TALLY", "N/A"))  # pyright: ignore[reportPrivateUsage]
    if reviewer or phase or vote:
        body = _wrap_oos_body(body, reviewer=reviewer, phase=phase, vote=vote)
    out = tmpdir / "oos-issue-bodies" / f"oos-body-{item_index}.txt"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(body, encoding="utf-8")
    return out


def _run_issue_batch(tmpdir: Path, combined: Path, *, repo: str, issue_number: str, deps_path: Path | None = None) -> BatchResult:
    bodies_dir = tmpdir / "oos-issue-bodies"
    bodies_dir.mkdir(parents=True, exist_ok=True)
    sanitized_input = bodies_dir / "oos-combined-sanitized.md"
    sanitized_input.write_text(file_oos._sanitize_public_text(combined.read_text(encoding="utf-8", errors="replace")), encoding="utf-8")  # pyright: ignore[reportPrivateUsage]

    parsed = _run_cli(["issue", "parse-input", "--input-file", str(sanitized_input), "--output-dir", str(bodies_dir)])
    if parsed.returncode != 0:
        _append_tool_failure(tmpdir, "step-9a1-oos-file", "issue parse-input", parsed.returncode, parsed.stderr or parsed.stdout)
        return BatchResult([], 1)
    fields = _parse_kv(parsed.stdout)
    total = int(fields.get("ITEMS_TOTAL", "0") or "0")
    if not _probe_tracking_blocker(tmpdir, repo, issue_number):
        return BatchResult([], 1)

    intra_batch_edges = _parse_intra_batch_deps(deps_path) if deps_path is not None else []
    create_order = _topological_create_order(total, intra_batch_edges)
    issue_numbers: dict[int, str] = {}

    filed: list[FiledIssue] = []
    failures = 0
    for item_index in create_order:
        title = file_oos._sanitize_public_text(fields.get(f"ITEM_{item_index}_TITLE", ""))  # pyright: ignore[reportPrivateUsage]
        body_file = _body_file_for_item(tmpdir, item_index, fields)
        args = [
            "issue",
            "create-one",
            "--title",
            title,
            "--title-prefix",
            "[OOS]",
            "--body-file",
            str(body_file),
        ]
        if repo:
            args.extend(["--repo", repo])
        created = _run_cli(args)
        kv = _parse_kv(created.stdout)
        if created.returncode != 0 or kv.get("ISSUE_FAILED") == "true":
            failures += 1
            _cleanup_created_issues(tmpdir, filed, repo=repo)
            return BatchResult(filed, failures)
        url = kv.get("ISSUE_URL") or kv.get(f"ISSUE_{item_index}_URL") or kv.get("ISSUE_DUPLICATE_OF_URL") or kv.get(f"ISSUE_{item_index}_DUPLICATE_OF_URL")
        duplicate = bool(kv.get("ISSUE_DUPLICATE_OF_URL") or kv.get(f"ISSUE_{item_index}_DUPLICATE_OF_URL"))
        if url:
            filed.append(FiledIssue(kv.get("ISSUE_TITLE") or title, url, duplicate))
        number = kv.get("ISSUE_NUMBER") or ""
        if number.isdigit():
            issue_numbers[item_index] = number
        if issue_number and number.isdigit():
            blocked = _run_cli(["issue", "add-blocked-by", "--client-issue", number, "--blocker-issue", issue_number, *([] if not repo else ["--repo", repo])])
            blocked_kv = _parse_kv(blocked.stdout)
            if blocked.returncode != 0 or blocked_kv.get("BLOCKED_BY_FAILED") == "true":
                detail = blocked_kv.get("ERROR") or blocked.stderr or blocked.stdout or "add-blocked-by failed"
                _append_tool_failure(tmpdir, "step-9a1-oos-file", "issue add-blocked-by", blocked.returncode or 1, detail)
                _cleanup_created_issues(tmpdir, filed, repo=repo)
                return BatchResult(filed, 1)
        for blocker_index, blocked_index in intra_batch_edges:
            if blocked_index != item_index:
                continue
            blocker_number = issue_numbers.get(blocker_index, "")
            blocked_number = issue_numbers.get(blocked_index, "")
            if not blocker_number.isdigit() or not blocked_number.isdigit():
                continue
            intra = _run_cli(
                [
                    "issue",
                    "add-blocked-by",
                    "--client-issue",
                    blocked_number,
                    "--blocker-issue",
                    blocker_number,
                    *([] if not repo else ["--repo", repo]),
                ],
            )
            intra_kv = _parse_kv(intra.stdout)
            if intra.returncode != 0 or intra_kv.get("BLOCKED_BY_FAILED") == "true":
                detail = intra_kv.get("ERROR") or intra.stderr or intra.stdout or "intra-batch add-blocked-by failed"
                _append_tool_failure(tmpdir, "step-9a1-oos-file", "issue add-blocked-by", intra.returncode or 1, detail)
                _cleanup_created_issues(tmpdir, filed, repo=repo)
                return BatchResult(filed, 1)
    return BatchResult(filed, failures)


def _write_sentinel(tmpdir: Path, filed: list[FiledIssue]) -> None:
    lines = ["| OOS title | Issue | URL |", "|---|---|---|"]
    for issue in filed:
        number = issue.url.rsplit("/", 1)[-1]
        lines.append(f"| {issue.title} | #{number} | {issue.url} |")
    lines.append("")
    lines.append(f"- **Filed**: {len(filed)}")
    (tmpdir / "oos-issues-created.md").write_text("\n".join(lines) + "\n", encoding="utf-8")


def _write_oos_ndjson(tmpdir: Path, run_id: str, filed: list[FiledIssue], *, status: str = "Filed") -> Path:
    run_dir = tmpdir / "larch-logs" / "implement" / run_id
    run_dir.mkdir(parents=True, exist_ok=True)
    path = run_dir / "oos-issues.ndjson"
    records: list[str] = []
    for issue in filed:
        body = f"## Accepted / Out-of-Scope Observations\n\n- **Disposition**: {status}\n- **Filed URL**: {issue.url}\n- **Title**: {issue.title}"
        record = {"phase": "implement", "step": "9a.1", "category": "OOS", "body": file_oos._sanitize_public_text(body)}  # pyright: ignore[reportPrivateUsage]
        records.append(json.dumps(record, separators=(",", ":")))
    path.write_text(("\n".join(records) + "\n") if records else "", encoding="utf-8")
    return path


def _write_run_statistics(tmpdir: Path, run_id: str, filed_count: int) -> Path:
    path = tmpdir / "larch-logs" / "implement" / run_id / "run-statistics.md"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(f"Run {run_id}: {filed_count} OOS issue(s) filed.\n", encoding="utf-8")
    return path


def _stamp_manifest(tmpdir: Path, run_id: str, *, value: bool) -> bool:
    manifest = tmpdir / "larch-logs" / "implement" / run_id / "manifest.json"
    if not manifest.is_file():
        return False
    result = _run_cli(
        [
            "run-log",
            "manifest",
            "--log-root",
            str(tmpdir / "larch-logs"),
            "--skill",
            "implement",
            "--run-id",
            run_id,
            "--field",
            f"steps_ran.step9a1={'true' if value else 'false'}",
        ],
    )
    if result.returncode != 0:
        detail = (result.stderr or result.stdout or "manifest update failed").strip()
        raise RuntimeError(f"run-log manifest steps_ran.step9a1 update failed: {detail[:300]}")
    return True


def _file(args: argparse.Namespace) -> tuple[int, dict[str, object]]:
    tmpdir = Path(args.implement_tmpdir)
    state = _read_kv_file(tmpdir / "ship-pr-state.sh")
    state = state | {k: v for k, v in {"REPO": args.repo or "", "ISSUE_NUMBER": str(args.issue_number or "")}.items() if v}
    run_id = _run_id(tmpdir, state)
    repo = str(args.repo or state.get("REPO", ""))
    issue_number = str(args.issue_number or state.get("ISSUE_NUMBER", ""))
    forked = _bool(state.get("FORKED_TARGET", "false"))
    repo_unavailable = _bool(state.get("REPO_UNAVAILABLE", "false"))
    security_sidecar = tmpdir / "security-oos-observations.md"
    if security_sidecar.is_file() and security_sidecar.stat().st_size > 0:
        msg = "security-routed OOS requires private SECURITY.md disposition before public OOS filing"
        _append_tool_failure(tmpdir, "step-9a1-oos-file", "oos file", 2, msg)
        return 2, {"status": "security_sidecar_present", "accepted_count": 0, "filed_count": 0, "deduplicated_count": 0, "urls": [], "run_statistics_written": False, "step9a1_stamped": False}

    manifest_path = Path(state.get("MANIFEST_PATH", ""))
    if manifest_path.is_file():
        try:
            _ = file_oos.materialize_manifest_oos(manifest_path, tmpdir)
        except (OSError, RuntimeError, ValueError) as exc:
            _append_warning(tmpdir, f"manifest OOS materialization failed: {exc}")

    blocks, already = _working_batch(tmpdir)
    accepted_count = len(blocks) + len(already)
    prior_sentinel = _sentinel_urls(tmpdir)
    if prior_sentinel and not blocks:
        filed = prior_sentinel
        _write_oos_ndjson(tmpdir, run_id, filed, status="Recovered from sentinel")
        stats = _write_run_statistics(tmpdir, run_id, len(filed))
        stamped = _stamp_manifest(tmpdir, run_id, value=True)
        return 0, {"status": "idempotent", "accepted_count": accepted_count, "filed_count": len(filed), "deduplicated_count": len(filed), "urls": [issue.url for issue in filed], "run_statistics_written": stats.is_file(), "step9a1_stamped": stamped}

    if not blocks:
        filed = already
        if filed:
            _write_oos_ndjson(tmpdir, run_id, filed, status="Already filed")
        stats = _write_run_statistics(tmpdir, run_id, len(filed))
        stamped = _stamp_manifest(tmpdir, run_id, value=bool(filed))
        return 0, {"status": "empty" if not filed else "already_filed", "accepted_count": accepted_count, "filed_count": len(filed), "deduplicated_count": len(filed), "urls": [issue.url for issue in filed], "run_statistics_written": stats.is_file(), "step9a1_stamped": stamped}

    if forked or repo_unavailable:
        status = "Skipped — repo unavailable" if repo_unavailable else "Skipped — forked target"
        filed = [FiledIssue(block.title, f"skipped://oos/{index}") for index, block in enumerate(blocks, start=1)]
        _write_oos_ndjson(tmpdir, run_id, filed, status=status)
        stats = _write_run_statistics(tmpdir, run_id, 0)
        stamped = _stamp_manifest(tmpdir, run_id, value=True)
        return 0, {"status": "skipped", "accepted_count": accepted_count, "filed_count": 0, "deduplicated_count": 0, "urls": [], "run_statistics_written": stats.is_file(), "step9a1_stamped": stamped}

    combined_text = _maybe_combine_with_codex(tmpdir, _render_blocks(blocks), codex_timeout=int(args.codex_timeout))
    combined = tmpdir / "oos-combined.md"
    combined.write_text(combined_text, encoding="utf-8")
    try:
        file_oos.issue_cap(combined)
    except (OSError, RuntimeError, ValueError) as exc:
        _append_tool_failure(tmpdir, "step-9a1-oos-file", "oos issue-cap", 1, str(exc))
        return 1, {"status": "issue_cap_failed", "accepted_count": accepted_count, "filed_count": 0, "deduplicated_count": 0, "urls": [], "run_statistics_written": False, "step9a1_stamped": False}
    deps = tmpdir / "oos-intra-batch-deps.tsv"
    try:
        deps.write_text("".join(f"{left}\t{right}\n" for left, right in file_oos.file_conflict_deps(combined)), encoding="utf-8")
    except OSError as exc:
        _append_warning(tmpdir, f"file-conflict pre-pass failed; continuing without intra-batch dependencies: {exc}")
    batch = _run_issue_batch(tmpdir, combined, repo=repo, issue_number=issue_number, deps_path=deps)
    if batch.failures:
        _append_tool_failure(tmpdir, "step-9a1-oos-file", "issue create-one", 1, f"ISSUES_FAILED={batch.failures}")
        return 1, {"status": "issue_batch_failed", "accepted_count": accepted_count, "filed_count": len(batch.filed), "deduplicated_count": len([issue for issue in batch.filed if issue.duplicate]), "urls": [issue.url for issue in batch.filed], "run_statistics_written": False, "step9a1_stamped": False}
    filed = [*prior_sentinel, *already, *batch.filed]
    seen_urls: set[str] = set()
    deduped: list[FiledIssue] = []
    for issue in filed:
        if issue.url in seen_urls:
            continue
        seen_urls.add(issue.url)
        deduped.append(issue)
    filed = deduped
    _write_sentinel(tmpdir, filed)
    _write_oos_ndjson(tmpdir, run_id, filed)
    stats = _write_run_statistics(tmpdir, run_id, len(filed))
    stamped = _stamp_manifest(tmpdir, run_id, value=True)
    return 0, {"status": "filed", "accepted_count": accepted_count, "filed_count": len(filed), "deduplicated_count": len([issue for issue in filed if issue.duplicate]), "urls": [issue.url for issue in filed], "run_statistics_written": stats.is_file(), "step9a1_stamped": stamped}


def cmd_file(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="cli.py oos file")
    parser.add_argument("--implement-tmpdir", required=True)
    parser.add_argument("--repo", default="")
    parser.add_argument("--issue-number", default="")
    parser.add_argument("--codex-timeout", default="300")
    try:
        args = parser.parse_args(argv)
        rc, payload = _file(args)
    except (OSError, RuntimeError, ValueError) as exc:
        rc = 1
        payload = {"status": "error", "error": str(exc), "accepted_count": 0, "filed_count": 0, "deduplicated_count": 0, "urls": [], "run_statistics_written": False, "step9a1_stamped": False}
    print(json.dumps(payload, separators=(",", ":")))
    return rc


if __name__ == "__main__":
    raise SystemExit(cmd_file())

    # Do NOT copy session-transcript-refresh.txt into the run tree: it is a
    # volatile in-loop snapshot that duplicates the canonical batch in nearly
    # all runs (issue #3708 Phase 1).
    out = Path(ctx.tmpdir) / "session-transcript-refresh.txt"
    return out if out.is_file() else None


def _read_finalize_kv(tmpdir: Path, key: str) -> str:
    return _read_kv_file(tmpdir / "finalize-state.sh", key)


def _read_run_flags_kv(tmpdir: Path, key: str) -> str:
    return _read_kv_file(tmpdir / "run-flags.sh", key)


def _step9a1_heuristic(ctx: RunContext) -> bool | None:
    tmpdir = Path(ctx.tmpdir)
    log_root = tmpdir / "larch-logs"
    run_id = effective_run_id(ctx)
    if not run_id:
        return None
    forked_target = _read_state_kv(ctx.state_file, "FORKED_TARGET") == "true"
    if ctx.forked or forked_target:
        return False
    design_done = _read_finalize_kv(tmpdir, "DESIGN_ONLY_DONE") == "true"
    no_issues = _read_run_flags_kv(tmpdir, "NO_ISSUES") == "true"
    if design_done and no_issues:
        return False
    run_dir = log_root / "implement" / run_id
    manifest_path = run_dir / "manifest.json"
    if manifest_path.is_file():
        with suppress(OSError, json.JSONDecodeError):
            if _manifest_step9a1_explicitly_skipped(json.loads(manifest_path.read_text(encoding="utf-8"))):
                return False
    ndjson = run_dir / "oos-issues.ndjson"
    if ndjson.is_file() and ndjson.stat().st_size > 0:
        return True
    stats = run_dir / "run-statistics.md"
    if stats.is_file():
        text = stats.read_text(encoding="utf-8", errors="replace")
        return not re.search(r":\s*0 OOS issue\(s\) filed\.", text)
    return None


def _publish_run_tree_to_repo(
    ctx: RunContext,
) -> bool:
    if condition == "always":
        return True
    if condition == "step5":
        return (
            _verify_has_file(run_dir, "code-review-tally.json")
            or _verify_has_file(run_dir, "review-findings-full.jsonl")
            or _verify_condition_reached(
                "step7a",
                run_dir,
                manifest_data,
                manifest_status=manifest_status,
                manifest_pr_number=manifest_pr_number,
            )
        )
    if condition == "step7a":
        if (
            _manifest_steps_ran_empty(manifest_data)
            and _final_summary_heading_bail_signal(run_dir)
            and not (
                _verify_has_file(run_dir, "token-report.json")
                or _verify_has_file(run_dir, "timing-report.json")
                or _verify_has_file(run_dir, "execution-issues.ndjson")
                or _verify_has_file(run_dir, "session-transcript.jsonl")
            )
        ):
            return False
        return (
            _verify_has_file(run_dir, "token-report.json")
            or _verify_has_file(run_dir, "timing-report.json")
            or _verify_has_file(run_dir, "execution-issues.ndjson")
            or _verify_has_file(run_dir, "session-transcript.jsonl")
            or _verify_condition_reached(
                "step8",
                run_dir,
                manifest_data,
                manifest_status=manifest_status,
                manifest_pr_number=manifest_pr_number,
            )
        )
    if condition == "step8":
        if (
            _manifest_steps_ran_empty(manifest_data)
            and _final_summary_heading_bail_signal(run_dir)
            and not _verify_has_file(run_dir, "version-bump-reasoning.md")
        ):
            return False
        return (
            _verify_has_file(run_dir, "version-bump-reasoning.md")
            or _verify_has_file(run_dir, "final-summary.md")
            or bool(manifest_pr_number)
            or _verify_condition_reached(
                "step9a1",
                run_dir,
                manifest_data,
                manifest_status=manifest_status,
                manifest_pr_number=manifest_pr_number,
            )
        )
    if condition == "step9a1":
        if _manifest_step9a1_explicitly_skipped(manifest_data):
            return False
        if (
            _manifest_steps_ran_empty(manifest_data)
            and _final_summary_heading_bail_signal(run_dir)
            and not (
                _verify_has_file(run_dir, "run-statistics.md")
                or _verify_has_file(run_dir, "oos-issues.ndjson")
            )
        ):
            return False
        if (
            _final_summary_heading_bail_signal(run_dir)
            and not _verify_has_file(run_dir, "run-statistics.md")
            and _manifest_steps_ran_nonempty_without_step9a1(manifest_data)
        ):
            return False
        return (
            _verify_has_file(run_dir, "run-statistics.md")
            or _verify_has_file(run_dir, "oos-issues.ndjson")
            or bool(manifest_pr_number)
            or manifest_status == config.MANIFEST_STATUS_DONE
            or _verify_has_file(run_dir, "final-summary.md")
        )
    if condition == "exn-agg-validate-fail":
        path = run_dir / "execution-issues.ndjson"
        return "N/A"
    if not isinstance(data_obj, dict):
        return "N/A"
    data = cast("dict[str, object]", data_obj)
    accepted = int(str(data.get("accepted_count") or 0))
    rejected = int(str(data.get("rejected_count") or 0))
    total = accepted + rejected
    if total <= 0:
        return "N/A"
    return f"{accepted}/{total} accepted"


def _derive_oos_fields(run_dir: Path) -> tuple[str, str]:
    ndjson = run_dir / "oos-issues.ndjson"
    if not ndjson.is_file():
        return "0", ""
    text = ndjson.read_text(encoding="utf-8", errors="replace")
    lines = [line for line in text.splitlines() if line.strip()]
    urls = sorted(set(re.findall(r"https://github\.com[^\"\\s>)]+", text)))
    return str(len(lines)), ",".join(urls)


def _derive_final_report_fields(
    implement_tmpdir: Path,
    *,
    run_id: str,
    repo: str,
    repo_unavailable: bool,
    pr_number: str,
    ship: Path,
) -> dict[str, str]:
    run_dir = implement_tmpdir / "larch-logs" / "implement" / run_id
    code_added, code_deleted, logs_added, logs_deleted = _derive_pr_line_counts(
        repo=repo,
        repo_unavailable=repo_unavailable,
        pr_number=pr_number,
        ship=ship,
    )
    plan_line = _read_kv(ship, "PLAN_REVIEW_LINE") or _derive_review_line(run_dir, "plan-review-tally.json")
    code_line = _read_kv(ship, "CODE_REVIEW_LINE") or _derive_review_line(run_dir, "code-review-tally.json")
    oos_count = _read_kv(ship, "OOS_COUNT") or _derive_oos_fields(run_dir)[0]
    oos_urls = _read_kv(ship, "OOS_URLS") or _derive_oos_fields(run_dir)[1]
    return {
        "plan_review_line": plan_line or "N/A",
        "code_review_line": code_line or "N/A",
        "code_added": code_added or _read_kv(ship, "CODE_ADDED"),
        "code_deleted": code_deleted or _read_kv(ship, "CODE_DELETED"),
        "logs_added": logs_added or _read_kv(ship, "LOGS_ADDED"),
        "logs_deleted": logs_deleted or _read_kv(ship, "LOGS_DELETED"),
        "oos_count": oos_count or "0",
        "oos_urls": oos_urls,
    }


def _stamp_skipped_steps_for_terminal_report(
    implement_tmpdir: Path,
    *,
    run_id: str,
    outcome: str,
) -> tuple[int, str]:
    if outcome == "merged" or not run_id or run_id == "unknown":
        return 0, ""
    run_dir = implement_tmpdir / "larch-logs" / "implement" / run_id
    manifest = run_dir / "manifest.json"
    if not manifest.is_file():
        return 0, ""
    fields: list[str] = []
    if not (run_dir / "run-statistics.md").is_file() and not (run_dir / "oos-issues.ndjson").is_file():
        fields.append("steps_ran.step9a1=false")
    if not (run_dir / "final-summary.md").is_file() and not (run_dir / "version-bump-reasoning.md").is_file():
        fields.append("steps_ran.step8=false")
    if not any(
        (run_dir / name).is_file()
        for name in (
            "token-report.json",
            "timing-report.json",
            "execution-issues.ndjson",
            "session-transcript.jsonl",
        )
    ):
        fields.append("steps_ran.step7a=false")
        if isinstance(data, dict) and isinstance(data.get("reviewer_signals"), list):
            any_meta = True
            signals.extend(x for x in data["reviewer_signals"] if isinstance(x, dict))
    return any_meta, signals


def _scan_required(run_dir: Path, pr: int, required: Path | None) -> dict[str, object] | tuple[dict[str, object], bool]:
    if required is None or not required.is_file():
        return {"scan": "required-file-presence", "pr": pr, "result": "skip", "detail": "required-files-tsv not provided"}
    manifest = _read_json_file(run_dir / "manifest.json")
    sr_raw = manifest.get("steps_ran") if isinstance(manifest, dict) else None
    sr = sr_raw if isinstance(sr_raw, dict) else {}
    def has(rel: str) -> bool:
        if "*" in rel:
            return any(p.is_file() for p in run_dir.glob(rel))
        return (run_dir / rel).is_file()
    def steps_false(c: str) -> bool:
        return sr.get(c) is False
    def empty_steps() -> bool:
        return isinstance(manifest, dict) and (sr_raw is None or (isinstance(sr_raw, dict) and not sr_raw))
    def bail_signal() -> bool:
        fs = run_dir / "final-summary.md"
        if not fs.is_file():
            return False
        for line in fs.read_text(encoding="utf-8", errors="replace").splitlines():
            if line.strip():
                return bool(_TERMINAL_RE.search(line.strip()))
        return False
    def nonempty_without_step9a1() -> bool:
        return bool(sr) and "step9a1" not in sr
    def cond(c: str, chain: bool = False) -> bool:
        if c == "always": return True
        if c == "step5":
            return not steps_false("step5") and (has("code-review-tally.json") or has("review-findings-full.jsonl") or cond("step7a"))
        if c == "step7a":
            if steps_false("step7a"): return False
            if empty_steps() and bail_signal() and not (has("token-report.json") or has("timing-report.json") or has("execution-issues.ndjson") or has("session-transcript.jsonl")): return False
            return has("token-report.json") or has("timing-report.json") or has("execution-issues.ndjson") or has("session-transcript.jsonl") or cond("step8")
        if c == "step8":
            if steps_false("step8"): return False
            if empty_steps() and bail_signal() and not has("version-bump-reasoning.md"): return False
            return has("version-bump-reasoning.md") or has("final-summary.md") or cond("step9a1", chain=True)
        if c == "step9a1":
            if steps_false("step9a1"): return False
            if empty_steps() and bail_signal() and not (has("run-statistics.md") or has("oos-issues.ndjson")): return False
            if bail_signal() and not has("run-statistics.md") and nonempty_without_step9a1(): return False
            return has("run-statistics.md") or has("oos-issues.ndjson") if chain else True
        if c == "exn-agg-validate-fail":
            f = run_dir / "execution-issues.ndjson"
            return f.is_file() and "merged output failed validation" in f.read_text(encoding="utf-8", errors="replace")
        if c == "exn-agg-dispatch-fail":
            f = run_dir / "execution-issues.ndjson"
            return f.is_file() and any(x in f.read_text(encoding="utf-8", errors="replace") for x in ("dispatch-with-waterfall exited non-zero", "DISPATCH_OK=false"))

    if repo.returncode != 0:
        raise ValueError("not inside a git work tree (need commit-range scan)")
    root = repo.stdout.strip()
    ok = subprocess.run(["git", "-C", root, "rev-list", "-1", commit_range], text=True, capture_output=True, check=False)  # noqa: S607
    if ok.returncode != 0:
        raise ValueError(f"invalid commit-range: {commit_range}")
    log = subprocess.run(["git", "-C", root, "log", "--format=%B", commit_range], text=True, capture_output=True, check=False)  # noqa: S607
    if log.returncode != 0:
        raise ValueError(f"invalid commit-range: {commit_range}")
    return len(_INLINE_TRIAGE_RE.findall(log.stdout))


def disposition_gate(*, accepted_files: list[Path], filed_url_files: list[Path], filed_url_strict_files: list[Path], commit_range: str, oos_issues_ndjson: Path | None = None, fork_mode: bool = False, repo_unavailable: bool = False) -> int:
    if fork_mode or repo_unavailable:
        return 0
    for path in accepted_files:
        if path.exists() and (not path.is_file() or not os.access(path, os.R_OK)):
            raise ValueError(f"accepted file path is not a readable regular file: {path}")
    if (
        oos_issues_ndjson
        and oos_issues_ndjson.is_file()
        and oos_issues_ndjson.stat().st_size > 0
        and not any(p.is_file() for p in accepted_files)
        and _count_urls_in_files([oos_issues_ndjson]) > 0
    ):
        raise ValueError("oos-issues.ndjson lists filed GitHub issue URLs but no --accepted-files paths exist as regular files (check CSV path list)")
    non_sec = count_non_security(tuple(str(p) for p in accepted_files))
    filed = _count_urls_in_files(filed_url_files + ([oos_issues_ndjson] if oos_issues_ndjson else [])) + _count_urls_in_files(filed_url_strict_files, strict=True)
    rejected = _count_rejected_from_ndjson(oos_issues_ndjson) if oos_issues_ndjson else 0
    inline = _count_inline_triage(commit_range)
    if non_sec == 0 or filed > 0 or inline >= non_sec or rejected >= non_sec:
        return 0
    print(f"oos-disposition-gate: FAIL non_security_oos={non_sec} filed_urls={filed} inline_triage_lines={inline} rejected_oos_markers={rejected} (commit-range {commit_range})", file=sys.stderr)
    return 1


def disposition_gate_main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="cli.py oos disposition-gate")
    parser.add_argument("--fork-mode", action="store_true")
    parser.add_argument("--repo-unavailable", action="store_true")
    parser.add_argument("--accepted-files")
    parser.add_argument("--filed-urls-file", action="append", default=[])
    parser.add_argument("--filed-urls-strict-file", action="append", default=[])
    parser.add_argument("--oos-issues-ndjson")
    parser.add_argument("--commit-range")
    try:
        args = parser.parse_args(argv)
        if args.fork_mode or args.repo_unavailable:
            return 0
        if not args.accepted_files or not args.commit_range or (not args.filed_urls_file and not args.filed_urls_strict_file):
            parser.print_usage(sys.stderr)
            return 2
        return disposition_gate(
            accepted_files=[Path(p) for p in args.accepted_files.split(",") if p],
            filed_url_files=[Path(p) for p in args.filed_urls_file],
            filed_url_strict_files=[Path(p) for p in args.filed_urls_strict_file],
            oos_issues_ndjson=Path(args.oos_issues_ndjson) if args.oos_issues_ndjson else None,
            commit_range=args.commit_range,
            fork_mode=args.fork_mode,
            repo_unavailable=args.repo_unavailable,
        )
    except ValueError as exc:
        print(f"oos-disposition-gate: {exc}", file=sys.stderr)
        return 2


def _read_kv_file(path: Path) -> dict[str, str]:
    out: dict[str, str] = {}
    if not path.is_file():
        return out
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        if "=" in line:
            key, value = line.split("=", 1)
            out[key] = value.strip("\r")
    return out


def _append_failure_log(log: Path, site: str, tool: str, rc: int, output: str) -> None:
    log.parent.mkdir(parents=True, exist_ok=True)
    with log.open("a", encoding="utf-8") as handle:
        handle.write(f"\n### Tool Failures\n- **{site}**: {tool} exited {rc}\n")
        if output:
            handle.write(output.rstrip() + "\n")


def disposition_checkpoint_main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="cli.py oos disposition-checkpoint")
    parser.add_argument("--implement-tmpdir", required=True)
    parser.add_argument("--design-tmpdir")
    try:
        args = parser.parse_args(argv)
    except SystemExit:
        return 2
    tmpdir = Path(args.implement_tmpdir)
    if not tmpdir.exists():
        print("oos-disposition-checkpoint: --implement-tmpdir not found", file=sys.stderr)
        return 2
    state = _read_kv_file(tmpdir / "ship-pr-state.sh") | _read_kv_file(tmpdir / "finalize-state.sh")
    forked = state.get("FORKED_TARGET", "false") == "true"
    repo_unavailable = state.get("REPO_UNAVAILABLE", "false") == "true"
    merge_base = subprocess.run(["git", "merge-base", "HEAD", "origin/main"], text=True, capture_output=True, check=False)  # noqa: S607
    if merge_base.returncode == 0 and merge_base.stdout.strip():
        commit_range = f"{merge_base.stdout.strip()}..HEAD"
    else:
        origin_main = subprocess.run(["git", "rev-parse", "--verify", "origin/main"], text=True, capture_output=True, check=False)  # noqa: S607
        if origin_main.returncode == 0:
            commit_range = "origin/main..HEAD"
        else:
            parent = subprocess.run(["git", "rev-parse", "--verify", "HEAD^"], text=True, capture_output=True, check=False)  # noqa: S607
            commit_range = "HEAD^..HEAD" if parent.returncode == 0 else "HEAD"
    run_id = state.get("RUN_ID", "")
    if not run_id and (tmpdir / "session-id").is_file():
        run_id = (tmpdir / "session-id").read_text(encoding="utf-8").strip()
    ndjson: Path | None = None
    if run_id:
        candidate = tmpdir / "larch-logs" / "implement" / run_id / "oos-issues.ndjson"
        if candidate.is_file():
            ndjson = candidate
    else:
        matches = sorted((tmpdir / "larch-logs" / "implement").glob("*/oos-issues.ndjson"))
        if len(matches) == 1:
            ndjson = matches[0]
        elif len(matches) > 1:
            msg = "implement: ambiguous oos-issues.ndjson without session-id; cannot pass --oos-issues-ndjson"
            (tmpdir / "oos-disposition-checkpoint.stderr.log").write_text(msg + "\n", encoding="utf-8")
            _append_failure_log(tmpdir / "execution-issues.md", "step-8-oos-checkpoint-validation", "oos-disposition-checkpoint", 2, msg)
            return 2
    design = Path(args.design_tmpdir) if args.design_tmpdir else Path(os.environ.get("DESIGN_TMPDIR", "")) if os.environ.get("DESIGN_TMPDIR") else None
    design_path = tmpdir / "oos-accepted-design.md"
    if design and (design / "oos-accepted-design.md").is_file():
        design_path = design / "oos-accepted-design.md"
    elif (tmpdir / "design-export" / "oos-accepted-design.md").is_file():
        design_path = tmpdir / "design-export" / "oos-accepted-design.md"
    accepted = [tmpdir / "oos-accepted-main-agent.md", design_path, tmpdir / "oos-accepted-review.md"]
    filed = [tmpdir / "oos-issues-created.md"]
    strict = [tmpdir / "oos-accepted-main-agent.md", design_path, tmpdir / "oos-accepted-review.md"]
    if not forked and not repo_unavailable:
        security_sidecar = tmpdir / "security-oos-observations.md"
        if security_sidecar.is_file() and security_sidecar.stat().st_size > 0:
            msg = "implement: security-routed manifest OOS requires private SECURITY.md disposition; refusing all-clear checkpoint"
            (tmpdir / "oos-disposition-checkpoint.stderr.log").write_text(msg + "\n", encoding="utf-8")
            _append_failure_log(tmpdir / "execution-issues.md", "step-8-oos-checkpoint-validation", "oos-disposition-checkpoint", 2, msg)
            return 2
        non_sec = count_non_security(tuple(str(p) for p in accepted if p.is_file()))
        if non_sec > 0 and (ndjson is None or not ndjson.is_file()):
            msg = "implement: non-security accepted OOS requires a resolved oos-issues.ndjson path for disposition gate (--oos-issues-ndjson); batch missing or undiscoverable"
            (tmpdir / "oos-disposition-checkpoint.stderr.log").write_text(msg + "\n", encoding="utf-8")
            _append_failure_log(tmpdir / "execution-issues.md", "step-8-oos-checkpoint-validation", "oos-disposition-checkpoint", 2, msg)
            return 2
    try:
        rc = disposition_gate(accepted_files=accepted, filed_url_files=filed, filed_url_strict_files=strict, oos_issues_ndjson=ndjson, commit_range=commit_range, fork_mode=forked, repo_unavailable=repo_unavailable)
    except ValueError as exc:
        msg = str(exc)
        (tmpdir / "oos-disposition-checkpoint.stderr.log").write_text(msg + "\n", encoding="utf-8")
        _append_failure_log(tmpdir / "execution-issues.md", "step-8-oos-checkpoint-validation", "oos-disposition-checkpoint", 2, msg)
        return 2
    if rc != 0:
        _append_failure_log(tmpdir / "execution-issues.md", "step-8-oos-checkpoint", "oos-disposition-gate", rc, "")
    return rc


# ---------------------------------------------------------------------------
# Idempotency: sentinel-based URL recovery
# ---------------------------------------------------------------------------
def read_filed_urls_from_sentinel(sentinel_path: str | None) -> list[str]:
    """Return GitHub issue URLs already recorded in the sentinel file."""
    if not sentinel_path or not Path(sentinel_path).is_file():
        return []
    url_re = _github_issue_url_pattern()
    text = Path(sentinel_path).read_text(encoding="utf-8")
    return url_re.findall(text)


# ---------------------------------------------------------------------------
# Accepted-OOS path resolution (bash checkpoint order)
# ---------------------------------------------------------------------------
def resolve_design_oos_path(tmpdir: Path) -> Path:
    """Resolve accepted design OOS path in bash checkpoint order."""
    design_tmpdir = os.environ.get("DESIGN_TMPDIR", "")
    if design_tmpdir:
        design_path = Path(design_tmpdir) / "oos-accepted-design.md"
        if design_path.is_file():
            return design_path
    exported = tmpdir / "design-export" / "oos-accepted-design.md"
    if exported.is_file():
        return exported
    return tmpdir / "oos-accepted-design.md"


def accepted_oos_paths(tmpdir: Path) -> tuple[str, ...]:
    """Return the canonical accepted-OOS file paths for the given tmpdir."""
    design_path = resolve_design_oos_path(tmpdir)
    return tuple(
        str(p)
        for p in (
            tmpdir / "oos-accepted-review.md",
            tmpdir / "oos-accepted-main-agent.md",
            design_path,
        )
    )

